import{_ as i,H as p,f as e,i as a}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"32 | 职场规划：面试准备，如何做大模型时代下的长远规划？","description":"","frontmatter":{},"headers":[{"level":2,"title":"阅读导航","slug":"阅读导航","link":"#阅读导航","children":[]},{"level":2,"title":"内功心法","slug":"内功心法","link":"#内功心法","children":[{"level":3,"title":"稳定性","slug":"稳定性","link":"#稳定性","children":[]},{"level":3,"title":"主动性","slug":"主动性","link":"#主动性","children":[]},{"level":3,"title":"匹配性","slug":"匹配性","link":"#匹配性","children":[]}]},{"level":2,"title":"外功招式","slug":"外功招式","link":"#外功招式","children":[{"level":3,"title":"概念","slug":"概念","link":"#概念","children":[]},{"level":3,"title":"基础","slug":"基础","link":"#基础","children":[]},{"level":3,"title":"进阶","slug":"进阶","link":"#进阶","children":[]},{"level":3,"title":"高阶","slug":"高阶","link":"#高阶","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI大模型系统实战/32｜职场规划：面试准备，如何做大模型时代下的长远规划？.md","filePath":"AI大模型系统实战/32｜职场规划：面试准备，如何做大模型时代下的长远规划？.md","lastUpdated":1795452834000}'),t={name:"AI大模型系统实战/32｜职场规划：面试准备，如何做大模型时代下的长远规划？.md"};function r(n,l,o,h,s,u){return p(),e("div",null,[...l[0]||(l[0]=[a('<h1 id="_32-职场规划-面试准备-如何做大模型时代下的长远规划" tabindex="-1">32 | 职场规划：面试准备，如何做大模型时代下的长远规划？ <a class="header-anchor" href="#_32-职场规划-面试准备-如何做大模型时代下的长远规划" aria-label="Permalink to &quot;32 | 职场规划：面试准备，如何做大模型时代下的长远规划？&quot;">​</a></h1><p>你好，我是 Tyler。</p><p>在之前的课程中，我们从多个角度深入探讨了大模型技术的商业逻辑和发展方向，包括OpenAI、产业界和技术本身。今天，我们将回顾之前的课程内容，讨论如何将所学知识应用于职业规划，帮助你在大模型时代下找到合适的职业方向。</p><p>即使你没有直接参与过 AI 大模型领域的工作或研究，也可以通过今天的课程去理解各个概念的含义，提高自身的认知水平，因为这项技术将成为与蒸汽机和内燃机一样的伟大技术，重构产业上下游的生产力格局，这和我们每个人都息息相关。</p><h2 id="阅读导航" tabindex="-1">阅读导航 <a class="header-anchor" href="#阅读导航" aria-label="Permalink to &quot;阅读导航&quot;">​</a></h2><p>这节课将分为内功心法和外功招式两个部分，内功心法是每个岗位、职级的同学都应该掌握的基础，外功招式则会根据岗位和职级的不同有所区分。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/32/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/32/1.png" alt=""></a></p><p>接下来，我们正式开始学习。我们先从内功心法说起，我会站在面试官的角度，聊一聊大厂在考察候选人时比较注重的几个方面。希望你能够知己知彼，并且以终为始，以这个要求来贯穿你的面试准备全过程。当然，这种方法不仅适用于面试，也适用于职业规划和晋升准备。</p><h2 id="内功心法" tabindex="-1">内功心法 <a class="header-anchor" href="#内功心法" aria-label="Permalink to &quot;内功心法&quot;">​</a></h2><p>在职业选择和面试过程中，有许多需要注意的地方。今天，我将从稳定性、主动性和匹配性三个方面展开讲解。这三个方面也是大多数组织要求面试官考察候选人的内容。</p><h3 id="稳定性" tabindex="-1">稳定性 <a class="header-anchor" href="#稳定性" aria-label="Permalink to &quot;稳定性&quot;">​</a></h3><p>首先，我不建议你长时间（比如超过十年）在同一家公司熬资历，因为从长远来看，这可能会削弱你的竞争力，增加职业风险。但拥有相对“稳定”和可预测的职业背景，能让你在工作中获得更多成长机会，也会让你的潜在雇主对你更放心。</p><p>因此，在面试中，你要保持不卑不亢的态度。每次职业选择都是你为数不多真正能够主动“选择”的机会之一，这是一个双向选择的过程，你要去的是一个至少会工作三到五年的公司。</p><p>保持这种态度，才能让你在与面试官的沟通过程中，表现出职业人该有的沉稳，收获他对你职业稳定性的认同。</p><h3 id="主动性" tabindex="-1">主动性 <a class="header-anchor" href="#主动性" aria-label="Permalink to &quot;主动性&quot;">​</a></h3><p>其次，要尊重面试官。在面试前做好充分准备，要明白这不仅仅是一个他问你答的过程，而是一次双方的交流。不要把所有的对话引导工作都交给面试官，这既会让他感到不悦，也容易使你处于被动地位。</p><p>在整个面试过程中，面试官会认真记录你的每个回答。如果你把提问的主动权完全交给他，你可能会陷入知识盲区，进入被动局面。</p><p>因此，在面试中，你需要提前准备，以一个完整的自我介绍作为开场白，引起对方的兴趣，并将对话引向自己熟悉的领域。建议使用自顶向下的方法来构建自我介绍，从你的个人背景开始，并明确告诉对方你的主要技术特长是什么。</p><h3 id="匹配性" tabindex="-1">匹配性 <a class="header-anchor" href="#匹配性" aria-label="Permalink to &quot;匹配性&quot;">​</a></h3><p>你可能会担心，如果自己的技术标签与目标岗位不符，是否会影响面试结果？这是一个常见的问题。专业方向的转换是持续学习的表现，这是一个优点，所以你不用过于担心。</p><p>但是，在面试前，务必仔细阅读职位描述，思考这个职位的要求与你的过去经验是否相符，以及匹配度有多高。如果匹配度不高，你需要付出额外的努力，梳理你的工作经验，分析你的优点和劣势，哪些工作你做过，哪些没有，在过去的经验中有哪些方面是相关且可以证明你能胜任的，比如你有过哪些成功的专业转换经验。然后，在自我介绍时，将这些信息传达给面试官。</p><p>总之，请务必准备多个案例，例如，你在过去的工作中面临的挑战，与职位相关的工作经历，以及你如何处理与上司意见不一致的情况。这些案例将构成对你的完整描述。</p><p>最后，当你表述时，建议使用 STAR（Situation，Task，Action，Result）方法，这是结构化面试中最常要求的表达方式。这样，你可以间接帮助面试官为你写好个人评价，省去了他总结的烦恼。</p><p>在面试前，你可以自己扮演面试官，围绕对方公司发展、职位要求和结构化面试的方法，提前编写一份面试官对你的评价，然后根据这个评价准备开场白和案例，这能让你提前发现自己的弱点和准备中的疏漏，进而在面试过程中把握主动，游刃有余。</p><p>相信我，单单通过这个流程梳理你已有的准备材料，就能让你大幅提升通过面试的概率。</p><h2 id="外功招式" tabindex="-1">外功招式 <a class="header-anchor" href="#外功招式" aria-label="Permalink to &quot;外功招式&quot;">​</a></h2><p>当然，上面是一些内功心法，它不直接作为你的面试内容，如果想要无往不利，还是要深入学习各个门派的“武功”，做到内外兼修。</p><h3 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h3><p>首先，我们将探讨如何学习和积累大模型技术领域的知识，支撑你的职业发展。</p><p>这里，我要强调的是概念知识，这是在这门课程中一再强调的重点。你需要确保你的认知与该领域的从业人员一致，不要随意作出似是而非的判断，也不要仅仅凭借字面理解来形成看法。</p><p>有时候一些先入为主的错误认知，需要巨大的成本才能纠正，甚至有些时候你发表的一些错误言论，很可能直接降低你在组织中的信誉，覆水难收。所以我建议在一开始就打好基本概念的基础，以免你在后续学习中基于错误的前提构建知识体系，浪费掉大量的学习时间。</p><p>最重要的建议是首先建立扎实的基础，了解该领域的基本概念。至少，你应该了解以下内容。</p><ul><li><p>大模型是一个学术概念吗？</p></li><li><p>什么样的模型才是基础模型？</p></li><li><p>AIGC（生成式人工智能）的定义是什么？</p></li><li><p>…</p></li></ul><p>此外，了解这项技术的历史，它是如何从不同的技术演变而来的，以及它的边界在哪里。比如后面这些问题就很典型。</p><ul><li><p>GPT（Generative Pre-trained Transformer）中的各个字母分别是什么意思？</p></li><li><p>其中的预训练模型的发展历史是什么样的？</p></li><li><p>其中的 Transformer 是从哪项技术演变而来的？</p></li><li><p>…</p></li></ul><p>还需要熟悉与大模型相关的各种技术，包括后面这些。</p><ul><li><p>人工智能的三大学派有哪些，特点分别是什么？</p></li><li><p>提示语工程的概念是什么？它是一项具体的技术吗？</p></li><li><p>具身智能的概念是什么，在大模型技术出现之前它是否存在？</p></li><li><p>…</p></li></ul><p>以上要求适用于大多数领域的同学，因为这里并不需要深入了解数学、工程或算法等专业知识，只需要理解通用的概念。</p><p>当然，即使你具备数学和工程背景，也建议重新学习这些基本概念，以确保你的理解准确。有时，相关专业的同学可能会轻视这些基本概念，导致遗漏，从而影响后续学习效率。</p><p>你可以看出，我更鼓励你明确各个概念的含义，提高自身的认知水平，然后再深入基础知识。</p><h3 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to &quot;基础&quot;">​</a></h3><p>接下来，是基础知识的准备。就基础知识而言，一般面试考察会涵盖以下几个主要领域。首先是人工智能的基础知识和深度学习模型的开发能力，其中包括：</p><ul><li><p>机器学习模型的训练过程是怎样的？</p></li><li><p>如何训练一个人工智能模型？</p></li><li><p>损失函数的作用是什么？</p></li><li><p>为什么要使用梯度下降法？是不是不用它就无法完成训练？</p></li><li><p>…</p></li></ul><p>其次，你需要了解各种机器学习模型的特点，比如后面这些内容。</p><ul><li><p>有 / 无监督学习的定义和适应场景是什么，为什么是先期应用最广的方法？</p></li><li><p>对比学习的特点是什么，为什么近年它的曝光频率越来越高？</p></li><li><p>三大学派分别有哪些代表性的算法?</p></li><li><p>…</p></li></ul><p>除了人工智能相关的知识，我们还强调了 AI 系统的基础知识，包括 AI 离线系统和在线系统，主要问题如下。</p><ul><li><p>AI 系统离线部分的主要模块有哪些？</p></li><li><p>AI 系统中数据的流动过程是怎样的？</p></li><li><p>如何以高效率、低成本的方式使用全量和增量数据来支撑 AI 系统？</p></li><li><p>在线系统中如何权衡性能和准确率？能举一些例子吗？</p></li><li><p>策略建模时需要考虑的关键因素有哪些？</p></li><li><p>AI 系统中在线系统与离线系统之间的关系是什么？</p></li><li><p>…</p></li></ul><p>在这些领域，不仅要求你理解概念，还要求你掌握一些具体的细节，并运用数学和编程工具完成任务。对于非技术背景的同学，重点不在深入技术细节（能做到当然更好），但了解各个算法的适用场景仍然很有必要，这是因为如果你能理解技术的背景和边界，将能大幅提高你和技术同学的沟通效率，也能识别出他所提出的任何蹩脚理由。</p><p>基础问题主要考察你对技术的掌握深度，包括基础技术原理和技术诞生背景的深刻理解。完成了这部分知识的准备之后呢，我们就可以进入下一个环节，也就是我们进阶知识的学习和准备。</p><h3 id="进阶" tabindex="-1">进阶 <a class="header-anchor" href="#进阶" aria-label="Permalink to &quot;进阶&quot;">​</a></h3><p>通常，进阶问题考察的不仅限于单一知识点，更多情况会出综合性问题。这类问题就好比我们上学时区分“良好”和“优秀”这两个级别的“拔高题”。面试官常利用这类题目测试候选人能力边界，判断是否符合预期。如果候选人对这类问题回答表现比较好，常常会得到额外加分。</p><p>接下来，你可以结合后面这些例子，直观感受一下这类问题有什么特点。</p><ul><li><p>LoRA 的算法和向量检索 ANN 中的 PQ 算法之间有哪些共同点？</p></li><li><p>Word2Vec、图神经网络、向量召回以及 Transformer 输入层中嵌入表示有哪些异同？</p></li><li><p>AIRC 系统中召回模块和 AIGC 系统中检索增强模块的异同点是什么？</p></li><li><p>提示语工程中哪里利用了类似注意力的机制？</p></li><li><p>降低模型使用成本的方法有哪些？这些方法之间有哪些联系？</p></li><li><p>…</p></li></ul><p>不难发现，这些问题强调“融会贯通”的能力，需要候选人深入理解每项技术的细节，且兼顾深度和广度，敏锐发现综合题目中涉及的各项技术有什么联系，并且察觉问题中隐藏的关键难点。显然，想要回答这类问题更依赖面试前更长周期的积累准备。如果你没能在之前的学习中建立坚实的理解，面试时就会感到无从下手。</p><p>因此，我鼓励你采用自顶向下的思维方式，在学习过程中理解技术的核心概念和背景，以确保正确理解知识，明白它们的定位和含义，从而达到融会贯通的程度。</p><h3 id="高阶" tabindex="-1">高阶 <a class="header-anchor" href="#高阶" aria-label="Permalink to &quot;高阶&quot;">​</a></h3><p>接下来是更高阶的问题，对没有实际产业经验的人来说会更具挑战性。不过别担心，在完成进阶阶段的问题准备后，你已经可以拿到进入 AI 大模型行业的门票。你可以在行业中继续积累更多经验，再来准备挑战更高阶的问题。当然，对于已在行业内的人来说，则一定要认真尝试解决更高阶的问题。</p><p>高阶内容的要点是，考察候选人是否全面地掌握了技术知识，并且深入理解技术的当前发展方向、商业循环、发展潜力和终局目标。这是因为高阶候选人既需要在管理层面展现领导能力和全局思考，同时也需要关注下属团队成员的发展和职业安全，因此对他们的要求更严格，他们所承担的责任也更大。</p><p>为了确保他们胜任，面试过程需要更全面的评估。以下是一些示例问题。</p><ul><li><p>你认为微软收购 OpenAI 后对大模型的竞争格局有何影响？</p></li><li><p>微软在收购 OpenAI 后的最佳选择是什么，是内部建设团队、渐进吸收 OpenAI 技术，还是大力投资 OpenAI，继续推动其业务发展？</p></li><li><p>比较百度和阿里云 AI 大模型发展模式的异同，说说它们各自的优劣势，以及它们在竞争中的关系。</p></li></ul><p>面试中还可能涉及一些更难回答的问题。</p><ul><li><p>在完成业务发展 KPI 制定和团队采购计划确定后，突然遇到半导体行业的封锁，导致缺乏足够的算力支持，你会如何应对？</p></li><li><p>如果你提前知道这种情况会发生，你会采取哪些预案？</p></li><li><p>目前，大模型技术的人才非常短缺，你如何在团队中建设你的人才梯队？</p></li><li><p>有哪些方法可以快速扩充你的 AI 大模型相关技术人力资源？</p></li></ul><p>此外，高阶问题通常需要综合考虑多种因素才能决策，例如公司迫切需要 AI 大模型的能力，应该采用哪种方式来实现这一目标？</p><ul><li><p>是否公司内部设立专门团队；</p></li><li><p>是否通过市场投资、收购或剥离内部团队的方式创建初创公司；</p></li><li><p>是否要通过投资组合降低风险；</p></li><li><p>是否使用赛马机制；</p></li><li><p>…</p></li></ul><p>相信你可以看出，这里需要候选人具备更多的行业思考和实践经验，而且这里的每个问题后面都跟着很多层的隐藏子问题，比如，如果选择设立公司内容团队，团队的成员该如何挑选等等这些，这需要候选人有丰富的管理经验，并具备大量的行业 know how。</p><p>我在前沿思考篇的内容里，提供了很多类似的思考，希望可以帮助你打开视野、提高认知。不难发现，从概念、基础走入进阶和高阶，越高的岗位考察就越深入，面试问题也更加综合、开放。相信结合你在行业里的观察和思考，会给出比课程里更精彩的答案，实现自己职业发展的质变。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天的内容告一段落，我们做个总结吧。</p><p>这节课主要从面试官的角度，为你分享了内功心法和外功招式，帮助你在面试和职业发展中更好地准备和展现自己。</p><p>相信你已经感受到，这节课中的内容看似是面试辅导，实际上是从面试这件事来激发大家的思考，提供一个职业发展规划的牵引，引起你对职业发展规划的重视。只有对概念深入理解，并对基础技术、专业技术和行业 know how 融会贯通，才能在职业发展中无往不利。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/32/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/32/2.png" alt=""></a></p><p>通过今天的内容学习，我相信在完成这节课的学习后，各位同学会了解到我在整个专栏课程设计中的考虑和思考，这些问题都是在产业一线会遇到的真实问题。如果你认真学习了专栏中的所有内容，你会发现对于今天课上提出的问题，都可以在课程中找到答案。</p><p>相信你学完这节课以后，会在这节课的细节中感受到我专栏课程设计中的诸多考量，这些问题都是在产业一线会遇到的真实问题。如果你认真学习了专栏中的所有内容，你会发现对于今天课上提出的问题，都可以在课程中找到解题思路。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>试着回答这节课中的所有示例问题。</p><p>恭喜你完成我们第 32 次打卡学习，期待你在留言区和我交流互动。如果你觉得有收获，也欢迎你分享给你身边的朋友，邀 TA 一起讨论。</p>',76)])])}const A=i(t,[["render",r]]);export{c as __pageData,A as default};
